  ('669134dd-55e9-5ab4-b190-a01f0204b665', null, (select id from public.skills where slug = 'read-g11-comparing-texts'), null, 'hard',
   $q$How do the final sentences of the two texts differ in what they suggest is the radio's greatest gift?$q$, $q$[{"text":"Text 1 stresses the gathering of strangers on a landing, while Text 2 stresses bringing faraway music into a farm kitchen.","is_correct":false,"misconception_token":"confuses-texts"},{"text":"Text 1 stresses bringing the distant world into one home, while Text 2 stresses the gathering itself, which continues even with no game on.","is_correct":true},{"text":"Both final sentences stress that the radio is valuable mainly because it delivers accurate weather forecasts to listeners.","is_correct":false,"misconception_token":"too-narrow"},{"text":"Both final sentences suggest the radio will soon be forgotten, since people tire of new inventions after a few weeks.","is_correct":false,"misconception_token":"unsupported-inference"}]$q$::jsonb, $q$Text 1 stresses bringing the distant world into one home, while Text 2 stresses the gathering itself, which continues even with no game on.$q$, $q$Text 1 ends with "the whole world had fit inside their kitchen," and Text 2 ends with tenants meeting "though no game was on." The weather report matters only in Text 1 and is not mentioned in either closing sentence.$q$, 'draft', '9d8c393f-48bf-5db3-a6a5-09caa47c9f27')
