  ('1f91a4c1-e96d-5a62-bf01-0e10f41fc754', null, (select id from public.skills where slug = 'read-g11-comparing-texts'), null, 'hard',
   $q$Which statement best describes how the two texts together treat the topic of the moon landing?$q$, $q$[{"text":"The landing is a private event that each character learns about alone, with no one else around to share it.","is_correct":false,"misconception_token":"too-narrow"},{"text":"The landing matters only to scientists, so ordinary people in homes and factories feel confused and left out by the news.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"The landing changes how the moon looks in the sky, which is why both characters stare at it for so long afterward.","is_correct":false,"misconception_token":"literal-reading"},{"text":"The landing briefly stops ordinary life for whole groups of people, yet each person makes sense of it in a private, individual way.","is_correct":true}]$q$::jsonb, $q$The landing briefly stops ordinary life for whole groups of people, yet each person makes sense of it in a private, individual way.$q$, $q$A living room and a factory line both go silent, then Tomasz and the speaker each reflect differently under the same moon. The moon looks "exactly as it always had," so it has not changed.$q$, 'draft', '6ebe01bc-a726-5127-b68d-6177561a23f1')
